import{_ as s}from"./chunks/embed-playground.DUFBb3fy.js";import{_ as t,o as i,c as a,a4 as n}from"./chunks/framework.ClGzHnIj.js";const h=JSON.parse('{"title":"Plongements","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://lognebudo.github.io/llmxray/docs/fr/guide/embeddings.html"}]]},"headers":[],"relativePath":"fr/guide/embeddings.md","filePath":"fr/guide/embeddings.md","lastUpdated":1791751393000}'),l={name:"fr/guide/embeddings.md"};function o(r,e,d,u,c,m){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="plongements" tabindex="-1">Plongements <a class="header-anchor" href="#plongements" aria-label="Permalink to &quot;Plongements&quot;">​</a></h1><p>La page Plongements vous permet de générer des embeddings textuels et de comparer visuellement la similarité sémantique entre deux textes.</p><p><strong>Élément de la barre latérale :</strong> Plongements <strong>Route :</strong> <code>/embeddings</code></p><p><img src="'+s+'" alt="Playground Plongements"></p><h2 id="qu-est-ce-qu-un-embedding" tabindex="-1">Qu&#39;est-ce qu&#39;un embedding ? <a class="header-anchor" href="#qu-est-ce-qu-un-embedding" aria-label="Permalink to &quot;Qu&#39;est-ce qu&#39;un embedding ?&quot;">​</a></h2><p>Un embedding est une liste de nombres (un vecteur) qui représente le sens d&#39;un texte. Des textes ayant des significations proches produisent des vecteurs pointant dans des directions similaires. LLMxRay utilise ce concept pour vous permettre d&#39;explorer la similarité sémantique de manière concrète.</p><h2 id="generer-un-embedding" tabindex="-1">Générer un embedding <a class="header-anchor" href="#generer-un-embedding" aria-label="Permalink to &quot;Générer un embedding&quot;">​</a></h2><ol><li>Sélectionnez un <strong>modèle d&#39;embedding</strong> dans le menu déroulant. Seuls les modèles ayant des capacités d&#39;embedding apparaissent (par ex., <code>nomic-embed-text</code>, <code>all-minilm</code>).</li><li>Saisissez du texte dans la zone de saisie.</li><li>Cliquez sur <strong>Embed</strong>. Le vecteur résultant est affiché sous forme de graphique à barres.</li></ol><div class="tip custom-block"><p class="custom-block-title">Pas de modèle d&#39;embedding ?</p><p>Si aucun modèle n&#39;apparaît dans le menu déroulant, vous devez en télécharger un :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nomic-embed-text</span></span></code></pre></div></div><h2 id="comparer-deux-textes" tabindex="-1">Comparer deux textes <a class="header-anchor" href="#comparer-deux-textes" aria-label="Permalink to &quot;Comparer deux textes&quot;">​</a></h2><ol><li>Saisissez du texte dans les deux zones de saisie.</li><li>Cliquez sur <strong>Comparer</strong>. Les deux textes sont transformés en embeddings et comparés.</li><li>Le <strong>compteur de similarité cosinus</strong> indique la proximité sémantique des deux textes : <ul><li><strong>1.0</strong> -- Signification identique</li><li><strong>0.7+</strong> -- Très similaire</li><li><strong>0.3-0.7</strong> -- Partiellement liés</li><li><strong>&lt; 0.3</strong> -- Sans rapport</li></ul></li></ol><h2 id="encoder-des-images" tabindex="-1">Encoder des images <a class="header-anchor" href="#encoder-des-images" aria-label="Permalink to &quot;Encoder des images&quot;">​</a></h2><p>Depuis Ollama 0.40, <code>/api/embed</code> accepte une image en plus du texte, sur les modèles qui déclarent à la fois les capacités <code>embedding</code> et <code>vision</code>. Quand le modèle sélectionné le fait, un contrôle <strong>Joindre une image</strong> apparaît sous la zone de texte du bac à sable et sous chaque côté du Calculateur de similarité. Un modèle texte seul n&#39;affiche aucun contrôle d&#39;image, parce que le démon répond aux médias par un 501.</p><p>Ce que vous pouvez en faire :</p><ul><li>Encoder une photo et une phrase qui la décrit, puis les comparer. Même espace vectoriel, donc la similarité cosinus a un sens.</li><li>Comparer deux photos.</li><li>Encoder une image seule, sans texte.</li></ul><p>Chaque résultat affiche les <strong>tokens d&#39;invite</strong> qu&#39;il a coûtés. Une image est un bloc fixe de tokens en plus du texte — mesuré sur embeddinggemma-2 : une phrase courte a coûté 7 tokens, la même phrase avec une image minuscule 265. Ce bloc se paie quelle que soit la taille de l&#39;image.</p><p><strong>Le seul modèle qui le fait aujourd&#39;hui, embeddinggemma-2, tourne sur le moteur MLX d&#39;Ollama, qui n&#39;existe que sur Apple Silicon.</strong> Sous Windows ou Linux, <code>ollama pull embeddinggemma-2</code> échoue avec « this model requires MLX support ». Pour l&#39;utiliser depuis une autre machine, redirigez le démon du Mac via SSH et pointez LLMxRay dessus dans les Paramètres :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ssh -L 11435:localhost:11434 utilisateur@votre-mac</span></span></code></pre></div><p>puis réglez l&#39;URL Ollama sur <code>http://localhost:11435/api</code>.</p><h2 id="cas-d-utilisation" tabindex="-1">Cas d&#39;utilisation <a class="header-anchor" href="#cas-d-utilisation" aria-label="Permalink to &quot;Cas d&#39;utilisation&quot;">​</a></h2><ul><li><strong>Comprendre les embeddings</strong> -- Voir ce que ces nombres représentent concrètement</li><li><strong>Tester la pertinence RAG</strong> -- Vérifier si vos documents correspondront aux requêtes des utilisateurs</li><li><strong>Explorer les synonymes</strong> -- Observer comment le modèle comprend les relations sémantiques</li><li><strong>Pédagogie</strong> -- Idéal pour les cours d&#39;IA/ML sur les représentations vectorielles</li></ul><h2 id="astuces" tabindex="-1">Astuces <a class="header-anchor" href="#astuces" aria-label="Permalink to &quot;Astuces&quot;">​</a></h2><ul><li>Différents modèles d&#39;embedding produisent des dimensions de vecteurs et des scores de similarité différents.</li><li>Des textes courts et ciblés produisent des comparaisons plus pertinentes que de longs paragraphes.</li><li>Les résultats sont stockés dans la session et peuvent être consultés ultérieurement.</li></ul>',23)])])}const b=t(l,[["render",o]]);export{h as __pageData,b as default};
